export const getDistrictBounds = (name: string): [[number, number], [number, number]] | null => {
  if (!name) return null;
  const cleanName = name.trim();

  // Try direct lookup case-insensitively
  let key = Object.keys(DISTRICT_BOUNDS).find(k => k.toLowerCase() === cleanName.toLowerCase());

  if (!key) {
    // Try variant mapping from DISTRICT_NAME_VARIANTS (e.g. Baleshwar vs Balasore, Sonepur vs Subarnapur)
    const normalized = DISTRICT_NAME_VARIANTS[cleanName] || cleanName;
    key = Object.keys(DISTRICT_BOUNDS).find(k => k.toLowerCase() === normalized.toLowerCase());

    // Try reverse variant mapping
    if (!key) {
      const revVariant = Object.keys(DISTRICT_NAME_VARIANTS).find(k => DISTRICT_NAME_VARIANTS[k] === cleanName);
      if (revVariant) {
        key = Object.keys(DISTRICT_BOUNDS).find(k => k.toLowerCase() === revVariant.toLowerCase());
      }
    }
  }

  if (key) {
    const b = DISTRICT_BOUNDS[key];
    return [[b.minx, b.miny], [b.maxx, b.maxy]];
  }
  return null;
};


export const getRecord = (dataObject: any, name: string): any => {
  if (!dataObject) return undefined;
  if (dataObject[name] !== undefined) return dataObject[name];

  // Try mapping name to its variant (canonical -> raw)
  const variant = Object.keys(DISTRICT_NAME_VARIANTS).find(
    (k) => DISTRICT_NAME_VARIANTS[k] === name
  );
  if (variant && dataObject[variant] !== undefined) return dataObject[variant];

  // Try mapping variant back to canonical (raw -> canonical)
  const canonical = DISTRICT_NAME_VARIANTS[name];
  if (canonical && dataObject[canonical] !== undefined) return dataObject[canonical];

  // Case-insensitive search fallback
  const lowerName = name.toLowerCase();
  const foundKey = Object.keys(dataObject).find(
    (k) => k.toLowerCase() === lowerName
  );
  if (foundKey !== undefined) return dataObject[foundKey];

  return undefined;
};

